const data = JSON.parse($input.first().json.stdout);

const items = data.reduce((acc, item) => {
  if (!item.quantity.length) return [...acc, 
                                     {
                                       name: item.name,
                                       amount: "",
                                       unit: "",
                                     }]
  return [...acc, 
          ...item.quantity.map(q => ({
            name: item.name,
            amount: q.value.value.value,
            unit: q.unit,
          }))
         ]
}, [])

return items.map(item => ({ json: { item } }));

