};

const recipes = $('Parse filepath').first().json.recipes
const removals = $('Revise').first().json.data.Replace
const picks = $input.first().json.recipes

const filtered = recipes.filter(rec => !removals.some(rem => rem === rec.name))

return ({
  json: { 
    recipes: [
      ...filtered,
      ...picks
    ]
  }
})

